КаталогБазы = Объект.КаталогСтруктурыТекущейБазы;
Результат = "";

ФайлКаталога = Новый Файл(КаталогБазы);
Если НЕ ФайлКаталога.Существует() Тогда
    Результат = "ОШИБКА: Каталог не найден: " + КаталогБазы;
Иначе
    КаталогОбработки = КаталогБазы + "/DataProcessors/ExtCntrl";
    ФайлОбработки = Новый Файл(КаталогОбработки);
    Если НЕ ФайлОбработки.Существует() Тогда
        Результат = "ОШИБКА: Каталог обработки не найден: " + КаталогОбработки;
    Иначе
        МассивФайлов = НайтиФайлы(КаталогОбработки, "*.bsl", Истина);
        Если МассивФайлов.Количество() = 0 Тогда
            Результат = "ОШИБКА: Файлы .bsl не найдены в " + КаталогОбработки;
        Иначе
            КлючевыеСловаGit = Новый Массив;
            КлючевыеСловаGit.Добавить("КаталогБазыЗнанийGit");
            КлючевыеСловаGit.Добавить("ТокенGit");
            КлючевыеСловаGit.Добавить("РепозиторийGit");
            КлючевыеСловаGit.Добавить("АдресGitAPI");
            КлючевыеСловаGit.Добавить("commit");
            КлючевыеСловаGit.Добавить("push");

            КлючевыеСловаPlanAct = Новый Массив;
            КлючевыеСловаPlanAct.Добавить("Plan");
            КлючевыеСловаPlanAct.Добавить("Act");
            КлючевыеСловаPlanAct.Добавить("PLAN");
            КлючевыеСловаPlanAct.Добавить("ACT");
            КлючевыеСловаPlanAct.Добавить("Режим");

            КлючевыеСлова = Новый Массив;
            КлючевыеСлова.Добавить("Заметк");
            КлючевыеСлова.Добавить("Знани");
            КлючевыеСлова.Добавить("note");
            КлючевыеСлова.Добавить("Note");

            Результат = "=== КОД-РЕВЬЮ: ЛОГИКА СОЗДАНИЯ ЗАМЕТОК (БАЗА ЗНАНИЙ GIT) ===" + Символы.ПС;
            Результат = Результат + "Каталог: " + КаталогОбработки + Символы.ПС;
            Результат = Результат + "Найдено файлов: " + МассивФайлов.Количество() + Символы.ПС + Символы.ПС;

            Для Каждого Файл Из МассивФайлов Цикл
                Чтение = Новый ЧтениеТекста(Файл.ПолноеИмя, КодировкаТекста.UTF8);
                Содержимое = Чтение.Прочитать();
                Чтение.Закрыть();

                ОтносительныйПуть = СтрЗаменить(Файл.ПолноеИмя, КаталогОбработки + "/", "");

                НайденоGit = "";
                Для Каждого Слово Из КлючевыеСловаGit Цикл
                    Если СтрНайти(Содержимое, Слово) > 0 Тогда
                        НайденоGit = НайденоGit + Слово + " ";
                    КонецЕсли;
                КонецЦикла;

                НайденоPlanAct = "";
                Для Каждого Слово Из КлючевыеСловаPlanAct Цикл
                    Если СтрНайти(Содержимое, Слово) > 0 Тогда
                        НайденоPlanAct = НайденоPlanAct + Слово + " ";
                    КонецЕсли;
                КонецЦикла;

                НайденоЗаметки = "";
                Для Каждого Слово Из КлючевыеСлова Цикл
                    Если СтрНайти(Содержимое, Слово) > 0 Тогда
                        НайденоЗаметки = НайденоЗаметки + Слово + " ";
                    КонецЕсли;
                КонецЦикла;

                Если ЗначениеЗаполнено(НайденоGit) ИЛИ ЗначениеЗаполнено(НайденоPlanAct) ИЛИ ЗначениеЗаполнено(НайденоЗаметки) Тогда
                    Результат = Результат + "--- ФАЙЛ: " + ОтносительныйПуть + " ---" + Символы.ПС;
                    Если ЗначениеЗаполнено(НайденоGit) Тогда
                        Результат = Результат + "  [Git]: " + СокрЛП(НайденоGit) + Символы.ПС;
                    КонецЕсли;
                    Если ЗначениеЗаполнено(НайденоPlanAct) Тогда
                        Результат = Результат + "  [Plan/Act]: " + СокрЛП(НайденоPlanAct) + Символы.ПС;
                    КонецЕсли;
                    Если ЗначениеЗаполнено(НайденоЗаметки) Тогда
                        Результат = Результат + "  [Заметки]: " + СокрЛП(НайденоЗаметки) + Символы.ПС;
                    КонецЕсли;
                    Результат = Результат + Символы.ПС;
                КонецЕсли;
            КонецЦикла;

            СистемныйПромптТекст = Объект.СистемныйПромпт;
            Результат = Результат + "=== АНАЛИЗ СИСТЕМНОГО ПРОМПТА ===" + Символы.ПС;
            Если ЗначениеЗаполнено(СистемныйПромптТекст) Тогда
                Результат = Результат + "Системный промпт заполнен: ДА" + Символы.ПС;
                Результат = Результат + "Длина: " + СтрДлина(СистемныйПромптТекст) + " символов" + Символы.ПС;
                Если СтрНайти(СистемныйПромптТекст, "Plan") > 0 ИЛИ СтрНайти(СистемныйПромптТекст, "PLAN") > 0 Тогда
                    Результат = Результат + "Упоминание Plan: ДА" + Символы.ПС;
                Иначе
                    Результат = Результат + "Упоминание Plan: НЕТ" + Символы.ПС;
                КонецЕсли;
                Если СтрНайти(СистемныйПромптТекст, "Act") > 0 ИЛИ СтрНайти(СистемныйПромптТекст, "ACT") > 0 Тогда
                    Результат = Результат + "Упоминание Act: ДА" + Символы.ПС;
                Иначе
                    Результат = Результат + "Упоминание Act: НЕТ" + Символы.ПС;
                КонецЕсли;
                Если СтрНайти(СистемныйПромптТекст, "Заметк") > 0 ИЛИ СтрНайти(СистемныйПромптТекст, "Знани") > 0 Тогда
                    Результат = Результат + "Упоминание заметок/знаний: ДА" + Символы.ПС;
                Иначе
                    Результат = Результат + "Упоминание заметок/знаний: НЕТ" + Символы.ПС;
                КонецЕсли;
            Иначе
                Результат = Результат + "Системный промпт: НЕ ЗАПОЛНЕН" + Символы.ПС;
            КонецЕсли;

            Результат = Результат + Символы.ПС + "=== ИТОГОВЫЕ ВЫВОДЫ ===" + Символы.ПС;
            Результат = Результат + "1. Проверьте файлы с упоминанием Git — там логика работы с базой знаний" + Символы.ПС;
            Результат = Результат + "2. Проверьте файлы с упоминанием Plan/Act — там логика переключения режимов" + Символы.ПС;
            Результат = Результат + "3. Системный промпт определяет поведение ИИ в разных режимах" + Символы.ПС;
        КонецЕсли;
    КонецЕсли;
КонецЕсли;
